"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def normalize_public_action(action):
    """Validate one public key or coordinate action without touching ``env``."""
    if isinstance(action, (list, tuple)):
        if (
            len(action) != 3
            or action[0] != 6
            or any(
                not isinstance(value, int) or isinstance(value, bool)
                for value in action
            )
        ):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        normalized = (6, int(action[1]), int(action[2]))
        if not (0 <= normalized[1] < 64 and 0 <= normalized[2] < 64):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        return normalized
    if (
        not isinstance(action, int)
        or isinstance(action, bool)
        or action not in range(1, 8)
    ):
        raise ValueError("key action must be an integer in 1..7")
    if action == 6:
        raise ValueError(
            "bare ACTION6 is invalid; use (6, x, y) with integer x,y in 0..63"
        )
    return int(action)


def safe_step(env, action):
    """Validate locally, then apply one public key or coordinate action."""
    normalized = normalize_public_action(action)
    if isinstance(normalized, tuple):
        env.step(*normalized)
    else:
        env.step(normalized)
    return normalized


def action_deltas(env, actions=None) -> Dict[object, dict]:
    """Compare valid cloned actions; bare ACTION6 is never sent to the arena."""
    if actions is None:
        actions = tuple(action for action in env.actions if action != 6)
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    base = arr(env.frame()).copy()
    out = {}
    for action in normalized_actions:
        clone = env.clone()
        safe_step(clone, action)
        out[action] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence):
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    clone = env.clone()
    for action in normalized_actions:
        if clone.terminal():
            break
        safe_step(clone, action)
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }

"""Reusable skills derived from public frame and action observations."""
from collections import deque

import numpy as np
from perception import arr, connected_components, safe_step


def reunite_mirrored_pair(env, floor_color=5, avatar_color=10, max_states=10000, hazard_colors=()):
    """Route a pair with shared vertical and opposite horizontal controls to meet.

    Infer square tiles and walkable cells from the frame, then search the joint
    positions. Remaining distance on this joint graph measures progress toward
    reunion, including detours needed to synchronize the pair against walls.
    Exclude actions that attempt to enter a supplied hazard color, since those
    reset the pair rather than blocking movement. Verify the complete route on
    a clone before applying it to the real arena.
    """
    frame = arr(env.frame())
    avatars = sorted(connected_components(frame, [avatar_color]),
                     key=lambda b: b.bbox[1])
    if len(avatars) != 2 or avatars[0].size != avatars[1].size:
        raise ValueError('Expected two equal square avatars')
    size, width = avatars[0].size
    if size != width:
        raise ValueError('Expected square tiles')
    start = tuple(b.top_left for b in avatars)
    oy, ox = start[0][0] % size, start[0][1] % size
    walkable = set()
    hazards = set()
    for y in range(oy, frame.shape[0] - size + 1, size):
        for x in range(ox, frame.shape[1] - size + 1, size):
            tile = frame[y:y + size, x:x + size]
            if np.any(np.isin(tile, hazard_colors)):
                hazards.add((y, x))
            if np.all((tile == floor_color) | (tile == avatar_color)):
                walkable.add((y, x))

    directions = {1: (-size, 0), 2: (size, 0),
                  3: (0, -size), 4: (0, size)}

    def advance(state, action):
        dy, dx = directions[action]
        result = []
        for index, (y, x) in enumerate(state):
            target = (y + dy, x + (dx if index == 0 else -dx))
            if target in hazards:
                return None
            result.append(target if target in walkable else (y, x))
        return tuple(result)

    queue = deque([start])
    parents = {start: None}
    target = None
    while queue and len(parents) <= max_states:
        state = queue.popleft()
        if state[0] == state[1]:
            target = state
            break
        for action in directions:
            successor = advance(state, action)
            if successor is not None and successor not in parents:
                parents[successor] = (state, action)
                queue.append(successor)
    if target is None:
        raise RuntimeError('No bounded reunion route found')
    path = []
    while parents[target] is not None:
        target, action = parents[target]
        path.append(action)
    path.reverse()

    clone = env.clone()
    base_level = env.levels_completed
    predicted = start
    for index, action in enumerate(path):
        safe_step(clone, action)
        predicted = advance(predicted, action)
        if clone.levels_completed > base_level:
            path = path[:index + 1]
            break
        current = arr(clone.frame())
        observed = tuple(sorted((y, x) for y, x in walkable
                                if np.all(current[y:y + size, x:x + size]
                                          == avatar_color)))
        if observed != tuple(sorted(predicted)):
            raise RuntimeError(f'Mirrored movement model failed clone verification at {index}: action={action}, predicted={predicted}, observed={observed}')
    if clone.levels_completed <= base_level:
        raise RuntimeError('Reunion did not complete the level on the clone')
    for action in path:
        safe_step(env, action)
        if env.levels_completed > base_level or env.terminal():
            break


def park_selectable_blockers(env, floor_color=5, avatar_color=10,
                             blocker_color=9, selected_color=11):
    """Select small blockers and park each in a reachable corridor dead end.

    Treat the number of blockers outside dead ends as dense progress. Infer
    tile spacing from the avatars, avoid occupied cells, and verify the whole
    parking sequence on a clone before committing it.
    """
    frame = arr(env.frame())
    avatars = connected_components(frame, [avatar_color])
    if len(avatars) != 2 or avatars[0].size != avatars[1].size:
        raise ValueError('Expected two equal avatars')
    size, width = avatars[0].size
    if size != width:
        raise ValueError('Expected square avatars')
    oy, ox = (v % size for v in avatars[0].top_left)
    occupied = {b.top_left for b in avatars}
    walkable = set()
    blockers = set()
    for y in range(oy, frame.shape[0] - size + 1, size):
        for x in range(ox, frame.shape[1] - size + 1, size):
            tile = frame[y:y + size, x:x + size]
            if np.all(np.isin(tile, (floor_color, avatar_color, blocker_color))):
                walkable.add((y, x))
                if np.any(tile == blocker_color):
                    blockers.add((y, x))
    directions = {1: (-size, 0), 2: (size, 0),
                  3: (0, -size), 4: (0, size)}

    def neighbors(position):
        y, x = position
        return [(a, (y + dy, x + dx))
                for a, (dy, dx) in directions.items()
                if (y + dy, x + dx) in walkable]

    leaves = {p for p in walkable if len(neighbors(p)) == 1}
    clone = env.clone()
    path = []

    def apply(action):
        safe_step(clone, action)
        path.append(action)

    def observed_cells(color):
        return {((b.bbox[0] - oy) // size * size + oy,
                 (b.bbox[1] - ox) // size * size + ox)
                for b in connected_components(clone.frame(), [color])}

    ay, ax = min(occupied)
    for start in sorted(blockers):
        if start in leaves:
            continue
        queue = deque([start])
        routes = {start: []}
        unavailable = (blockers - {start}) | occupied
        while queue:
            position = queue.popleft()
            for action, target in neighbors(position):
                if target not in routes and target not in unavailable:
                    routes[target] = routes[position] + [action]
                    queue.append(target)
        options = (leaves & routes.keys()) - unavailable - {start}
        if not options:
            raise RuntimeError('No free reachable dead end for blocker')
        target = min(options, key=lambda p: (len(routes[p]), p))
        by, bx = start
        center = size // 2
        apply((6, bx + center, by + center))
        position = start
        if observed_cells(selected_color) != {start}:
            raise RuntimeError('Blocker selection failed clone verification')
        for action in routes[target]:
            apply(action)
            dy, dx = directions[action]
            position = (position[0] + dy, position[1] + dx)
            if observed_cells(selected_color) != {position}:
                raise RuntimeError('Blocker movement failed clone verification')
        apply((6, ax + center, ay + center))
        blockers.remove(start)
        blockers.add(target)
        if (observed_cells(blocker_color) != blockers
                or observed_cells(avatar_color) != occupied):
            raise RuntimeError('Parking failed clone verification')
    for action in path:
        safe_step(env, action)

# Per-level players only compose reusable legs.
from legs import reunite_mirrored_pair, park_selectable_blockers


def play_level_1(env):
    reunite_mirrored_pair(env)


def play_level_2(env):
    reunite_mirrored_pair(env, hazard_colors=(8,))


def play_level_3(env):
    park_selectable_blockers(env)
    reunite_mirrored_pair(env, hazard_colors=(8,))
import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop

